//! Authored-content schemas for the audio capability.
//!
//! `music_registry.ron` declares pre-rendered tracks and asset requirements;
//! `sfx_registry.ron` declares procedural cues; a `music_cue_catalog` file
//! declares adaptive cues and their bindings. Cue preparation checks the graph.
//! Registry handlers use their types' `validate()` methods. They add source diagnostics,
//! unknown-field rejection, and content identities. `music_registry.ron` is
//! generated by `scripts/regen/regen_music_registry.py`.

use std::sync::Arc;

use ambition_content_pack::{
    AssetRequirement, CapabilityId, ContentSchemaHandler, DiagnosticCode, FacetOutcome,
    FacetSource, RuntimeDisposition, SchemaId, SchemaRegistration, SchemaVersion,
};

use crate::cue_program::PreparedMusicCues;
use crate::cue_spec::{AuthoredMusicCues, MusicCueMedia};
use crate::music_media::MusicMediaCatalog;
use crate::spec::{MusicRegistry, SfxRegistry};

/// The capability that owns both schemas here.
pub const AUDIO_CAPABILITY: &str = "audio";

pub const MUSIC_REGISTRY_SCHEMA: &str = "music_registry";
/// One playable track.
pub const MUSIC_TRACK_SCHEMA: &str = "music_track";
pub const SFX_REGISTRY_SCHEMA: &str = "sfx_registry";
/// One procedural cue.
pub const SFX_CUE_SCHEMA: &str = "sfx_cue";

/// Adaptive cues and their encounter bindings.
pub const MUSIC_CUE_CATALOG_SCHEMA: &str = "music_cue_catalog";
/// One adaptive cue.
pub const MUSIC_CUE_SCHEMA: &str = "music_cue";
/// One encounter's binding to a cue.
pub const ENCOUNTER_MUSIC_BINDING_SCHEMA: &str = "encounter_music_binding";
/// One room's binding to a cue.
pub const ROOM_MUSIC_BINDING_SCHEMA: &str = "room_music_binding";
/// One boss's binding to a cue.
pub const BOSS_MUSIC_BINDING_SCHEMA: &str = "boss_music_binding";

pub const MUSIC_REGISTRY_VERSION: SchemaVersion = SchemaVersion(1);
pub const MUSIC_CUE_CATALOG_VERSION: SchemaVersion = SchemaVersion(2);
pub const SFX_REGISTRY_VERSION: SchemaVersion = SchemaVersion(1);

fn canonical<T: std::fmt::Debug>(value: &T) -> String {
    format!("{value:?}")
}

// ── music ────────────────────────────────────────────────────────────────────

struct MusicRegistrySchema;

impl ContentSchemaHandler for MusicRegistrySchema {
    fn check(&self, facet: &FacetSource<'_>, out: &mut FacetOutcome) {
        let registry: MusicRegistry = match facet.parse() {
            Ok(registry) => registry,
            Err(diagnostic) => {
                out.report(diagnostic.fix(GENERATED_FIX));
                return;
            }
        };

        // Reuse the registry's canonical validation rules.
        if let Err(message) = registry.validate() {
            out.report(
                facet
                    .diagnostic(DiagnosticCode::MalformedProviderBinding, message)
                    .fix(GENERATED_FIX),
            );
        }

        // Registry-level state must reach the fingerprint, which covers only
        // `out.define(...)` entries. Per-track entries alone would leave
        // `default_track` and track order out, and both matter at runtime
        // (`AudioLibrary` resolves the default at startup and indexes
        // `music_tracks[next]` for next/prev).
        out.define(facet.content_id_in(MUSIC_REGISTRY_SCHEMA, "registry"), {
            // Serialized, not `join(",")`: track ids may contain commas, so an
            // unescaped delimiter lets two different orders encode the same.
            let order: Vec<&str> = registry.tracks.iter().map(|t| t.id.as_str()).collect();
            format!(
                "default_track={}\norder={}",
                ron::ser::to_string(&registry.default_track)
                    .unwrap_or_else(|_| registry.default_track.clone()),
                ron::ser::to_string(&order).unwrap_or_else(|e| format!("<uncanonical: {e}>"))
            )
        });

        for track in &registry.tracks {
            let id = facet.content_id_in(MUSIC_TRACK_SCHEMA, &track.id);
            out.define(id.clone(), canonical(track));
            // The asset check: `AudioCatalogFragment` validates the registry's
            // shape but not whether the OGG exists.
            out.need_asset(AssetRequirement::new(
                track.resolved_asset_path(),
                id,
                "asset_path",
            ));
        }

        if !out.failed() {
            out.lower(registry);
        }
    }
}

const GENERATED_FIX: &str =
    "⛔ `music_registry.ron` is GENERATED by scripts/regen/regen_music_registry.py — fix the generator \
     or the asset tree, not this file, because the next render overwrites it";

// ── sfx ──────────────────────────────────────────────────────────────────────

struct SfxRegistrySchema;

impl ContentSchemaHandler for SfxRegistrySchema {
    fn check(&self, facet: &FacetSource<'_>, out: &mut FacetOutcome) {
        let registry: SfxRegistry = match facet.parse() {
            Ok(registry) => registry,
            Err(diagnostic) => {
                out.report(diagnostic);
                return;
            }
        };

        if let Err(message) = registry.validate() {
            out.report(facet.diagnostic(DiagnosticCode::MalformedProviderBinding, message));
        }

        // Same fingerprint gap as music: `sample_rate` is registry-level and
        // changes synthesis for every cue.
        out.define(
            facet.content_id_in(SFX_REGISTRY_SCHEMA, "registry"),
            format!("sample_rate={}", registry.sample_rate),
        );

        // A procedural cue has no asset; it is the synthesis spec. Identities
        // still let a caller name what a provider authorized.
        for spec in &registry.sfx {
            // Named by what the author wrote (the open `id` or the typed cue),
            // not the hashed `SfxId`, which is unreadable in a diagnostic.
            // A spec whose id does not resolve is reported by `validate()`;
            // do not mint an identity for it.
            if spec.sfx_id().is_err() {
                continue;
            }
            let name = match (&spec.id, spec.cue) {
                (Some(id), _) => id.clone(),
                (None, Some(cue)) => format!("{cue:?}"),
                (None, None) => continue,
            };
            out.define(facet.content_id_in(SFX_CUE_SCHEMA, name), canonical(spec));
        }

        if !out.failed() {
            out.lower(registry);
        }
    }
}

// ── adaptive music cues ──────────────────────────────────────────────────────

/// The phases of the day a room's track can be keyed by: the keys of
/// `ambition_time::DayPhase` (this crate does not depend on the clock; a test
/// in the content crate holds the two lists together).
pub use crate::cue_program::DAY_PHASE_KEYS;

struct MusicCueCatalogSchema;

impl ContentSchemaHandler for MusicCueCatalogSchema {
    fn check(&self, facet: &FacetSource<'_>, out: &mut FacetOutcome) {
        let authored: AuthoredMusicCues = match facet.parse() {
            Ok(authored) => authored,
            Err(diagnostic) => {
                out.report(diagnostic);
                return;
            }
        };

        let references: Vec<_> = authored
            .cues
            .iter()
            .filter_map(|cue| match &cue.media {
                MusicCueMedia::Published { description, .. } => Some(description.as_str()),
                MusicCueMedia::Inline { .. } => None,
            })
            .collect();
        let media = if references.is_empty() {
            MusicMediaCatalog::default()
        } else {
            let Some(snapshot) = facet.libraries else {
                out.report(facet.diagnostic(
                    DiagnosticCode::MalformedSource,
                    "published music needs an explicit selected library snapshot",
                ));
                return;
            };
            match MusicMediaCatalog::from_snapshot(snapshot, references) {
                Ok(media) => media,
                Err(errors) => {
                    for error in errors {
                        out.report(facet.diagnostic(DiagnosticCode::MalformedSource, error));
                    }
                    return;
                }
            }
        };
        out.define(
            facet.content_id("catalog"),
            canonical(&authored.room_phase_tracks),
        );
        for cue in &authored.cues {
            let product = match &cue.media {
                MusicCueMedia::Published { description, .. } => media.get(description),
                MusicCueMedia::Inline { .. } => None,
            };
            out.define(
                facet.content_id_in(MUSIC_CUE_SCHEMA, &cue.id),
                canonical(&(cue, product)),
            );
        }
        for binding in &authored.encounter_bindings {
            out.define(
                facet.content_id_in(ENCOUNTER_MUSIC_BINDING_SCHEMA, &binding.encounter_id),
                canonical(binding),
            );
        }
        for binding in &authored.room_bindings {
            out.define(
                facet.content_id_in(ROOM_MUSIC_BINDING_SCHEMA, &binding.room_id),
                canonical(binding),
            );
        }
        for binding in &authored.boss_bindings {
            out.define(
                facet.content_id_in(BOSS_MUSIC_BINDING_SCHEMA, &binding.boss_id),
                canonical(binding),
            );
        }

        match PreparedMusicCues::prepare(authored, &media) {
            Ok(prepared) if !out.failed() => {
                for cue in prepared.cues() {
                    for section in &cue.sections {
                        for source in &section.sources {
                            out.need_asset(AssetRequirement::new(
                                &source.path,
                                facet.content_id_in(MUSIC_CUE_SCHEMA, &cue.id),
                                "media",
                            ));
                        }
                    }
                }
                out.lower(prepared);
            }
            Ok(_) => {}
            Err(errors) => {
                for message in errors {
                    out.report(facet.diagnostic(DiagnosticCode::MalformedSource, message));
                }
            }
        }
    }
}

// ── lowered accessors — the runtime's load path ──────────────────────────────

pub fn lowered_music_registry(
    pack: &ambition_content_pack::PreparedContentPack,
) -> Option<&MusicRegistry> {
    pack.lowered::<MusicRegistry>(&SchemaId::new(MUSIC_REGISTRY_SCHEMA))
}

pub fn lowered_sfx_registry(
    pack: &ambition_content_pack::PreparedContentPack,
) -> Option<&SfxRegistry> {
    pack.lowered::<SfxRegistry>(&SchemaId::new(SFX_REGISTRY_SCHEMA))
}

/// The adaptive cues a prepared pack lowered, if it carries a cue file.
pub fn lowered_music_cues(
    pack: &ambition_content_pack::PreparedContentPack,
) -> Option<&PreparedMusicCues> {
    pack.lowered::<PreparedMusicCues>(&SchemaId::new(MUSIC_CUE_CATALOG_SCHEMA))
}

// ── registrations ────────────────────────────────────────────────────────────

pub fn music_registry_schema() -> SchemaRegistration {
    SchemaRegistration {
        id: SchemaId::new(MUSIC_REGISTRY_SCHEMA),
        version: MUSIC_REGISTRY_VERSION,
        capability: CapabilityId::new(AUDIO_CAPABILITY),
        disposition: RuntimeDisposition::Runtime,
        doc: "Radio and room music: one pre-rendered track per row, plus the default. \
              Defines `music_track` identities and requires each track's audio file. GENERATED.",
        handler: Arc::new(MusicRegistrySchema),
    }
}

pub fn sfx_registry_schema() -> SchemaRegistration {
    SchemaRegistration {
        id: SchemaId::new(SFX_REGISTRY_SCHEMA),
        version: SFX_REGISTRY_VERSION,
        capability: CapabilityId::new(AUDIO_CAPABILITY),
        disposition: RuntimeDisposition::Runtime,
        doc: "Procedural sound-design cues: the synth sample rate, one waveform/envelope \
              spec per cue, and the ids the provider keeps silent. Defines `sfx_cue` identities.",
        handler: Arc::new(SfxRegistrySchema),
    }
}

pub fn music_cue_catalog_schema() -> SchemaRegistration {
    SchemaRegistration {
        id: SchemaId::new(MUSIC_CUE_CATALOG_SCHEMA),
        version: MUSIC_CUE_CATALOG_VERSION,
        capability: CapabilityId::new(AUDIO_CAPABILITY),
        disposition: RuntimeDisposition::Runtime,
        doc: "Adaptive music: each cue's sections, layers and states, and the encounters \
              and rooms that bind to a cue. Defines `music_cue`, `encounter_music_binding` \
              and `room_music_binding` identities and requires each section's audio file.",
        handler: Arc::new(MusicCueCatalogSchema),
    }
}

